import sys

data = sys.stdin.read().split()
if not data:
    sys.exit()

try:
    nums = [int(x) for x in data]
    all_int = True
except ValueError:
    nums = [float(x) for x in data]
    all_int = False

s = sum(nums)
p = 1
for n in nums:
    p *= n

if all_int:
    print(s, p)
else:
    def fmt(v):
        if v == int(v):
            return str(int(v))
        return str(v)
    print(fmt(s), fmt(p))

