class Ext:
    MAX_STRENGTH = 1000

    @classmethod
    def set_max_strength(cls, n):
        if not isinstance(n, int) or n < 0:
            raise ValueError("MAX_STRENGTH must be a non-negative integer")
        cls.MAX_STRENGTH = n

    @classmethod
    def get_max_strength(cls):
        return cls.MAX_STRENGTH

    def __init__(self, strength):
        if not isinstance(strength, int):
            raise TypeError("strength must be an integer")
        self.strength = min(strength, self.MAX_STRENGTH)

    def extend(self, amount):
        if not isinstance(amount, int):
            raise TypeError("amount must be an integer")
        self.strength = min(self.strength + amount, self.MAX_STRENGTH)

    def __repr__(self):
        return f"Ext(strength={self.strength}, max={self.MAX_STRENGTH})"

if __name__ == "__main__":
    # Example usage
    a = Ext(1200)
    print(a)  # Ext(strength=1000, max=1000)

    Ext.set_max_strength(900)
    b = Ext(800)
    print(b)  # Ext(strength=800, max=900)

    b.extend(150)
    print(b)  # Ext(strength=900, max=900)

import sys

s = sys.stdin.read()

# Flip case for letters
flipped = []
for ch in s:
    if ch.isalpha():
        flipped.append(ch.upper() if ch.islower() else ch.lower())
    else:
        flipped.append(ch)

# For vowels in the result, advance by 2 ASCII codes
res = []
for ch in ''.join(flipped):
    if ch.lower() in 'aeiou':
        res.append(chr(ord(ch) + 2))
    else:
        res.append(ch)

sys.stdout.write(''.join(res))

